    visited[r][c] = true;
    dfs(r + 1, c);
    dfs(r - 1, c);
    dfs(r, c + 1);
    dfs(r, c - 1);
  }

  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) {
      if (grid[i][j] === 1 && !visited[i][j]) {
        count++;
        dfs(i, j);
      }
    }
  }
  return count;
}

function countIslands(grid) {
  if (!grid || grid.length === 0) return 0;

  const visited = new Set();
  let count = 0;

  for (let row = 0; row < grid.length; row++) {
    for (let col = 0; col < (grid[row] || []).length; col++) {
      const key = `${row},${col}`;
      if (grid[row][col] !== 1 || visited.has(key)) continue;

      count++;
      const stack = [[row, col]];
      visited.add(key);

      while (stack.length) {
        const [r, c] = stack.pop();
        const neighbors = [
          [r - 1, c],
          [r + 1, c],
          [r, c - 1],
          [r, c + 1]
        ];

        for (const [nr, nc] of neighbors) {
          if (
            nr >= 0 &&
            nr < grid.length &&
            nc >= 0 &&
            nc < (grid[nr] || []).length &&
            grid[nr][nc] === 1
          ) {
            const neighborKey = `${nr},${nc}`;
            if (!visited.has(neighborKey)) {
              visited.add(neighborKey);
              stack.push([nr, nc]);
            }
          }
        }
      }
    }
  }

  return count;
}

