function balancedOutsideQuotes(s) {
  const stack = [];
  let inQuotes = false;

  for (let i = 0; i < s.length; i++) {
    const ch = s[i];

    if (ch === '\\') {
      i++;
      continue;
    }

    if (ch === '"') {
      inQuotes = !inQuotes;
      continue;
    }

    if (inQuotes) continue;

    if (ch === '(' || ch === '[' || ch === '{') {
      stack.push(ch);
    } else if (ch === ')' || ch === ']' || ch === '}') {
      const open = stack.pop();
      if (
        (ch === ')' && open !== '(') ||
        (ch === ']' && open !== '[') ||
        (ch === '}' && open !== '{')
      ) {
        return false;
      }
    }
  }

  return !inQuotes && stack.length === 0;
}

