  const scaled = [];
  for (let i = 0; i < weights.length; i++) scaled.push(weights[i] / sum);
  const rounded = scaled.map(v => Math.round(v * 10000) / 10000);
  let roundedSum = 0;
  for (let i = 0; i < rounded.length; i++) roundedSum += rounded[i];
  let remainder = Math.round((1 - roundedSum) * 10000) / 10000;
  let maxIdx = 0;
  for (let i = 1; i < weights.length; i++) {
    if (weights[i] > weights[maxIdx]) maxIdx = i;
  }
  rounded[maxIdx] = Math.round((rounded[maxIdx] + remainder) * 10000) / 10000;
  return rounded;
}

function normalizeWeights(weights) {
  if (weights.length === 0) return null;

  let total = 0;
  let largestIndex = 0;

  for (let i = 0; i < weights.length; i++) {
    total += weights[i];
    if (weights[i] > weights[largestIndex]) {
      largestIndex = i;
    }
  }

  if (total === 0) return null;

  const result = weights.map(weight => Math.round((weight / total) * 10000) / 10000);
  const sum = result.reduce((acc, value) => acc + value, 0);
  result[largestIndex] += 1 - sum;

  return result;
}

