function reverseWordsKeepGaps(s) {
  if (s === '') return '';
  const tokens = [];
  let i = 0;
  while (i < s.length) {
    const isSpace = s[i] === ' ';
    let j = i;
    while (j < s.length && s[j] === (isSpace ? ' ' : s[i])) j++;
    tokens.push(s.slice(i, j));
    i = j;
  }
  const words = tokens.filter(t => t[0] !== ' ');
  const gaps = tokens.filter(t => t[0] === ' ');
  const reversedWords = words.reverse();
  const result = [];
  let wIdx = 0, gIdx = 0;
  for (const t of tokens) {
    if (t[0] !== ' ') {
      result.push(reversedWords[wIdx++]);
    } else {
      result.push(gaps[gIdx++]);
    }
  }
  return result.join('');
}

