function countNQueensSolutions(n) {
  let count = 0;
  const cols = new Set();
  const diag1 = new Set();
  const diag2 = new Set();

  function backtrack(row) {
    if (row === n) {
      count++;
      return;
    }
    for (let col = 0; col < n; col++) {
      if (cols.has(col) || diag1.has(row - col) || diag2.has(row + col)) {
        continue;
      }
      cols.add(col);
      diag1.add(row - col);
      diag2.add(row + col);
      backtrack(row + 1);
      cols.delete(col);
      diag1.delete(row - col);
      diag2.delete(row + col);
    }
  }

  backtrack(0);
  return count;
}

function countNQueensSolutions(n) {
  const size = BigInt(n);
  const full = (1n << size) - 1n;
  let count = 0n;

  function search(columns, diagonals1, diagonals2) {
    if (columns === full) {
      count++;
      return;
    }

    let available = full & ~(columns | diagonals1 | diagonals2);
    while (available) {
      const bit = available & -available;
      available -= bit;
      search(
        columns | bit,
        ((diagonals1 | bit) << 1n) & full,
        (diagonals2 | bit) >> 1n
      );
    }
  }

  search(0n, 0n, 0n);
  return Number(count);
}

