  dp[0] = true;
  for (const num of nums) {
    for (let i = target; i >= num; i--) {
      if (dp[i - num]) dp[i] = true;
    }
  }
  return dp[target];
}

function hasSubsetSum(nums, target) {
  const dp = new Uint8Array(target + 1);
  dp[0] = 1;

  for (const num of nums) {
    if (num > target) continue;
    for (let sum = target; sum >= num; sum--) {
      if (dp[sum - num]) dp[sum] = 1;
    }
    if (dp[target]) return true;
  }

  return target === 0 || !!dp[target];
}

function parseCsvLine(line) {
  const fields = [];
  let current = '';
  let inQuotes = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (inQuotes) {
      if (ch === '"') {
        if (i + 1 < line.length && line[i + 1] === '"') {
          current += '"';
          i++;
        } else {
          inQuotes = false;
        }
      } else {
        current += ch;
      }
    } else {
      if (ch === '"') {
        inQuotes = true;
      } else if (ch === ',') {
        fields.push(current);
        current = '';
      } else {
        current += ch;
      }
    }
  }
  fields.push(current);
  return fields;
}

function parseCsvLine(line) {
  const fields = [];
  let i = 0;

  while (true) {
    let field = "";

    if (i < line.length && line[i] === '"') {
      i++;
      while (i < line.length) {
        if (line[i] === '"') {
          if (i + 1 < line.length && line[i + 1] === '"') {
            field += '"';
            i += 2;
          } else {
            i++;
            break;
          }
        } else {
          field += line[i++];
        }
      }
    } else {
      const start = i;
      while (i < line.length && line[i] !== ',') i++;
      field = line.slice(start, i);
    }

    fields.push(field);

    if (i < line.length && line[i] === ',') {
      i++;
      continue;
    }

    break;
  }

  return fields;
}

function evalArithmetic(expr) {
  const tokens = expr.replace(/\s+/g, '').split('').map((c, i) => {
    if (/[\d]/.test(c)) {
      let j = i;
      while (j < expr.length - 1 && /[\d]/.test(expr[j + 1])) j++;
      return parseFloat(expr.substring(i, j + 1));
    }
    return c;
  }).filter(t => t !== undefined);

  let pos = 0;

  function parseExpr() {
    let left = parseTerm();
    while (pos < tokens.length && (tokens[pos] === '+' || tokens[pos] === '-')) {
      const op = tokens[pos++];
      const right = parseTerm();
      left = op === '+' ? left + right : left - right;
    }
    return left;
  }

  function parseTerm() {
    let left = parseFactor();
    while (pos < tokens.length && (tokens[pos] === '*' || tokens[pos] === '/')) {
      const op = tokens[pos++];
      const right = parseFactor();
      left = op === '*' ? left * right : left / right;
    }
    return left;
  }

  function parseFactor() {
    if (tokens[pos] === '(') {
      pos++;
      const val = parseExpr();
      pos++; // skip ')'
      return val;
    }
    const val = tokens[pos++];
    return typeof val === 'number' ? val : Number(val);
  }

  return parseExpr();
}

function evalArithmetic(expr) {
  let i = 0;

  function skipSpaces() {
    while (i < expr.length && expr[i] === ' ') i++;
  }

  function parseFactor() {
    skipSpaces();
    if (expr[i] === '(') {
      i++;
      const value = parseExpression();
      skipSpaces();
      i++;
      return value;
    }

    const start = i;
    while (i < expr.length && expr.charCodeAt(i) >= 48 && expr.charCodeAt(i) <= 57) i++;
    return Number(expr.slice(start, i));
  }

  function parseTerm() {
    let value = parseFactor();
    while (true) {
      skipSpaces();
      const operator = expr[i];
      if (operator !== '*' && operator !== '/') break;
      i++;
      const next = parseFactor();
      value = operator === '*' ? value * next : value / next;
    }
    return value;
  }

  function parseExpression() {
    let value = parseTerm();
    while (true) {
      skipSpaces();
      const operator = expr[i];
      if (operator !== '+' && operator !== '-') break;
      i++;
      const next = parseTerm();
      value = operator === '+' ? value + next : value - next;
    }
    return value;
  }

  return parseExpression();
}

function shortestPathLength(graph, start, end) {
    if (start === end) return 0;
    const queue = [[start, 0]];
    const visited = new Set([start]);
    let head = 0;
    while (head < queue.length) {
        const [node, dist] = queue[head++];
        const neighbors = graph[node] || [];
        for (const neighbor of neighbors) {
            if (neighbor === end) return dist + 1;
            if (!visited.has(neighbor)) {
                visited.add(neighbor);
                queue.push([neighbor, dist + 1]);
            }
        }
    }
    return -1;
}

function shortestPathLength(graph, start, end) {
  if (start === end) return 0;

  const visited = new Set([start]);
  const queue = [[start, 0]];
  let index = 0;

  while (index < queue.length) {
    const [node, distance] = queue[index++];
    const neighbors = Object.prototype.hasOwnProperty.call(graph, node)
      ? graph[node]
      : [];

    for (const neighbor of neighbors) {
      if (neighbor === end) return distance + 1;
      if (!visited.has(neighbor)) {
        visited.add(neighbor);
        queue.push([neighbor, distance + 1]);
      }
    }
  }

  return -1;
}

function minParenRemovals(s) {
  let open = 0;
  let removals = 0;
  for (let i = 0; i < s.length; i++) {
    if (s[i] === '(') {
      open++;
    } else {
      if (open > 0) {
        open--;
      } else {
        removals++;
      }
    }
  }
  return removals + open;
}

function minParenRemovals(s) {
  let balance = 0;
