}

function isValidTopoOrder(graph, order) {
  const n = Object.keys(graph).length;
  if (order.length !== n) return false;
  const seen = new Set();
  for (const node of order) {
    if (seen.has(node) || !(node in graph)) return false;
    seen.add(node);
  }
  const pos = {};
  for (let i = 0; i < order.length; i++) {
    pos[order[i]] = i;
  }
  for (const u of Object.keys(graph)) {
    for (const v of graph[u]) {
      if (pos[u] >= pos[v]) return false;
    }
  }
  return true;
}

function isValidTopoOrder(graph, order) {
  const nodes = Object.keys(graph);
  if (!Array.isArray(order) || order.length !== nodes.length) return false;

  const positions = new Map();

  for (let i = 0; i < order.length; i++) {
    const node = order[i];
    if (!Object.prototype.hasOwnProperty.call(graph, node) || positions.has(node)) {
      return false;
    }
    positions.set(node, i);
  }

  for (const u of nodes) {
    for (const v of graph[u]) {
      if (positions.get(u) >= positions.get(v)) return false;
    }
  }

  return true;
}

function countStairWays(n, steps) {
  const memo = new Map();
  function dfs(remaining) {
    if (remaining === 0) return 1;
    if (remaining < 0) return 0;
    if (memo.has(remaining)) return memo.get(remaining);
    let total = 0;
    for (const step of steps) {
      total += dfs(remaining - step);
    }
    memo.set(remaining, total);
    return total;
  }
  return dfs(n);
}

function countStairWays(n, steps) {
  const dp = Array(n + 1).fill(0);
  dp[0] = 1;

  for (let sum = 1; sum <= n; sum++) {
    for (const step of steps) {
      if (step <= sum) dp[sum] += dp[sum - step];
    }
  }

  return dp[n];
}

function maxNonOverlappingIntervals(intervals) {
  const sorted = intervals.slice().sort((a, b) => a[1] - b[1]);
  let count = 0;
  let lastEnd = -Infinity;
  for (const [, end] of sorted) {
    if (lastEnd <= end) {
      count++;
      lastEnd = end;
    }
  }
  return count;
}

