function hasDirectedCycle(graph) {
  const state = {};
  for (const node of Object.keys(graph)) {
    state[node] = 0;
  }
  for (const neighbors of Object.values(graph)) {
    for (const neighbor of neighbors) {
      if (!(neighbor in state)) {
        state[neighbor] = 0;
      }
    }
  }
  function dfs(node) {
    state[node] = 1;
    const neighbors = graph[node] || [];
    for (const neighbor of neighbors) {
      if (state[neighbor] === 1) {
        return true;
      }
      if (state[neighbor] === 0) {
        if (dfs(neighbor)) {
          return true;
        }
      }
    }
    state[node] = 2;
    return false;
  }
  for (const node of Object.keys(state)) {
    if (state[node] === 0) {
      if (dfs(node)) {
        return true;
      }
    }
  }
  return false;
}

function hasDirectedCycle(graph) {
  const state = Object.create(null);
  const hasOwn = Object.prototype.hasOwnProperty;

  function visit(node) {
    state[node] = 1;

    for (const neighbor of graph[node]) {
      if (!hasOwn.call(graph, neighbor)) continue;
      if (state[neighbor] === 1) return true;
      if (state[neighbor] === undefined && visit(neighbor)) return true;
    }

    state[node] = 2;
    return false;
  }

  for (const node of Object.keys(graph)) {
    if (state[node] === undefined && visit(node)) return true;
  }

  return false;
}

function longestPalindromicSubseqLength(s) {
  if (s.length === 0) return 0;
  const n = s.length;
  const dp = Array.from({ length: n }, () => new Array(n).fill(0));
  for (let i = n - 1; i >= 0; i--) {
    dp[i][i] = 1;
    for (let j = i + 1; j < n; j++) {
      if (s[i] === s[j]) {
        dp[i][j] = 2 + dp[i + 1][j - 1];
      } else {
        dp[i][j] = Math.max(dp[i + 1][j], dp[i][j - 1]);
      }
    }
  }
  return dp[0][n - 1];
}

function longestPalindromicSubseqLength(s) {
  const n = s.length;
  if (n === 0) return 0;

  const dp = new Array(n).fill(1);

  for (let i = n - 2; i >= 0; i--) {
    let prev = 0;
    for (let j = i + 1; j < n; j++) {
      const current = dp[j];
      if (s[i] === s[j]) {
        dp[j] = prev + 2;
      } else {
        dp[j] = Math.max(dp[j], dp[j - 1]);
      }
      prev = current;
    }
  }

  return dp[n - 1];
}

function twoSumIndices(nums, target) {
  for (let j = 1; j < nums.length; j++) {
    for (let i = 0; i < j; i++) {
      if (nums[i] + nums[j] === target) {
        return [i, j];
      }
    }
