function mergeIntervals(intervals) {
  if (intervals.length === 0) return [];
  const sorted = intervals.slice().sort((a, b) => a[0] - b[0]);
  const result = [];
  let current = [sorted[0][0], sorted[0][1]];
  for (let i = 1; i < sorted.length; i++) {
    const interval = sorted[i];
    if (interval[0] <= current[1]) {
      current[1] = Math.max(current[1], interval[1]);
    } else {
      result.push(current);
      current = [interval[0], interval[1]];
    }
  }
  result.push(current);
  return result;
}

function mergeIntervals(intervals) {
  if (intervals.length === 0) return [];

  const sorted = intervals.map(([start, end]) => [start, end]).sort((a, b) => a[0] - b[0]);
  const merged = [[sorted[0][0], sorted[0][1]]];

  for (let i = 1; i < sorted.length; i++) {
    const [start, end] = sorted[i];
    const last = merged[merged.length - 1];

    if (start <= last[1]) {
      last[1] = Math.max(last[1], end);
    } else {
      merged.push([start, end]);
    }
  }

  return merged;
}

function runLengthEncode(s) {
  if (s.length === 0) return '';
  let result = '';
  let count = 1;
  for (let i = 1; i < s.length; i++) {
    if (s[i] === s[i - 1]) {
      count++;
    } else {
      result += s[i - 1] + count;
      count = 1;
    }
  }
  result += s[s.length - 1] + count;
  return result;
}

function runLengthEncode(s) {
  if (s.length === 0) return '';

  let result = '';
  let current = s[0];
  let count = 1;

  for (let i = 1; i < s.length; i++) {
    if (s[i] === current) {
      count++;
    } else {
      result += current + count;
      current = s[i];
      count = 1;
    }
  }

  return result + current + count;
}

function spiralOrder(matrix) {
  if (!matrix.length || !matrix[0].length) return [];
  const result = [];
  let top = 0, bottom = matrix.length - 1;
  let left = 0, right = matrix[0].length - 1;
  while (top <= bottom && left <= right) {
    for (let i = left; i <= right; i++) result.push(matrix[top][i]);
    top++;
    for (let i = top; i <= bottom; i++) result.push(matrix[i][right]);
    right--;
    if (top <= bottom) {
      for (let i = right; i >= left; i--) result.push(matrix[bottom][i]);
      bottom--;
    }
    if (left <= right) {
      for (let i = bottom; i >= top; i--) result.push(matrix[i][left]);
      left++;
    }
  }
  return result;
}

function spiralOrder(matrix) {
  if (!matrix.length || !matrix[0].length) return [];

  const result = [];
  let top = 0;
  let bottom = matrix.length - 1;
  let left = 0;
  let right = matrix[0].length - 1;

  while (top <= bottom && left <= right) {
    for (let col = left; col <= right; col++) {
      result.push(matrix[top][col]);
    }
    top++;

    for (let row = top; row <= bottom; row++) {
      result.push(matrix[row][right]);
    }
    right--;

    if (top <= bottom) {
      for (let col = right; col >= left; col--) {
        result.push(matrix[bottom][col]);
      }
      bottom--;
    }

    if (left <= right) {
      for (let row = bottom; row >= top; row--) {
        result.push(matrix[row][left]);
      }
      left++;
    }
  }

  return result;
}

function intToBase(n, base) {
  if (n === 0) return '0';
  const digits = '0123456789abcdef';
  let negative = n < 0;
  let num = negative ? -n : n;
  let result = '';
  while (num > 0) {
    result = digits[num % base] + result;
    num = Math.floor(num / base);
  }
  return negative ? '-' + result : result;
}

function intToBase(n, base) {
  const digits = '0123456789abcdef';
  if (n === 0) return '0';

  const sign = n < 0 ? '-' : '';
  n = Math.abs(n);

  let result = '';
  while (n > 0) {
    result = digits[n % base] + result;
    n = Math.floor(n / base);
  }

  return sign + result;
}

function longestUniqueSubstring(s) {
  if (!s) return 0;
  let maxLen = 0;
  let start = 0;
  const charIndex = {};
  for (let end = 0; end < s.length; end++) {
    const char = s[end];
    if (charIndex.hasOwnProperty(char) && charIndex[char] >= start) {
      start = charIndex[char] + 1;
    }
    charIndex[char] = end;
    maxLen = Math.max(maxLen, end - start + 1);
  }
  return maxLen;
}

function longestUniqueSubstring(s) {
  const lastSeen = new Map();
  let start = 0;
  let maxLength = 0;

  for (let i = 0; i < s.length; i++) {
    const char = s[i];

    if (lastSeen.has(char) && lastSeen.get(char) >= start) {
      start = lastSeen.get(char) + 1;
    }

    lastSeen.set(char, i);
    maxLength = Math.max(maxLength, i - start + 1);
  }

  return maxLength;
}

function sortByFrequency(nums) {
  if (nums.length === 0) return [];
  const freq = {};
  for (const n of nums) {
    freq[n] = (freq[n] || 0) + 1;
  }
  const sorted = [...nums].sort((a, b) => {
    if (freq[a] !== freq[b]) return freq[b] - freq[a];
    return a - b;
  });
  return sorted;
}

function sortByFrequency(nums) {
  const frequencies = new Map();

  for (const num of nums) {
    frequencies.set(num, (frequencies.get(num) || 0) + 1);
  }

  return [...nums].sort((a, b) => {
    const frequencyDifference = frequencies.get(b) - frequencies.get(a);
    return frequencyDifference || a - b;
  });
}

function dayOfYear(y, m, d) {
  const isLeap = (y % 4 === 0 && y % 100 !== 0) || (y % 400 === 0);
  const daysInMonth = [31, isLeap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  let dayOfYear = 0;
  for (let i = 0; i < m - 1; i++) {
    dayOfYear += daysInMonth[i];
  }
  return dayOfYear + d;
}

function dayOfYear(y, m, d) {
  const leap = y % 4 === 0 && (y % 100 !== 0 || y % 400 === 0);
  const days = [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return d + days.slice(0, m).reduce((sum, value) => sum + value, 0) + (leap && m > 2 ? 1 : 0);
}

function evaluateRPN(tokens) {
  const stack = [];
  for (const token of tokens) {
    if (token === '+' || token === '-' || token === '*' || token === '/') {
      const b = stack.pop();
      const a = stack.pop();
      let result;
      if (token === '+') result = a + b;
      else if (token === '-') result = a - b;
      else if (token === '*') result = a * b;
      else result = Math.trunc(a / b);
      stack.push(result);
    } else {
      stack.push(parseInt(token));
    }
  }
  return stack.pop();
}

function evaluateRPN(tokens) {
  const stack = [];

  for (const token of tokens) {
    if (token === "+" || token === "-" || token === "*" || token === "/") {
      const right = stack.pop();
      const left = stack.pop();

      if (token === "+") stack.push(left + right);
      else if (token === "-") stack.push(left - right);
      else if (token === "*") stack.push(left * right);
      else stack.push(Math.trunc(left / right));
    } else {
      stack.push(Number(token));
    }
  }

  return stack[0];
}

function compressRanges(arr) {
  if (arr.length === 0) return '';
  const parts = [];
  let start = arr[0];
  let prev = arr[0];
  for (let i = 1; i < arr.length; i++) {
    if (arr[i] === prev + 1) {
      prev = arr[i];
    } else {
      if (start === prev) {
        parts.push(String(start));
      } else {
        parts.push(start + '-' + prev);
      }
      start = arr[i];
      prev = arr[i];
    }
  }
  if (start === prev) {
    parts.push(String(start));
  } else {
    parts.push(start + '-' + prev);
  }
  return parts.join(',');
}

function parseDuration(s) {
  if (typeof s !== "string" || s.length === 0) return null;
  const match = s.match(/^(?:(\d+)d)?(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$/);
  if (!match || !/[dhms]/.test(s)) return null;
  return Number(match[1] || 0) * 86400 +
    Number(match[2] || 0) * 3600 +
    Number(match[3] || 0) * 60 +
    Number(match[4] || 0);
}

function compressRanges(values) {
  if (values.length === 0) return '';

  const result = [];
  let start = values[0];
  let end = values[0];

  for (let i = 1; i < values.length; i++) {
    if (values[i] === end + 1) {
      end = values[i];
    } else {
      result.push(start === end ? String(start) : `${start}-${end}`);
      start = end = values[i];
    }
  }

  result.push(start === end ? String(start) : `${start}-${end}`);
  return result.join(',');
}

function mergeSortedArrays(a, b) {
  const result = [];
  let i = 0, j = 0;
  while (i < a.length || j < b.length) {
    if (j >= b.length || (i < a.length && a[i] <= b[j])) {
      result.push(a[i]);
      i++;
    } else {
      result.push(b[j]);
      j++;
    }
  }
  return result;
}

function mergeSortedArrays(a, b) {
  const result = [];
  let i = 0;
  let j = 0;

  while (i < a.length && j < b.length) {
    if (a[i] <= b[j]) {
      result.push(a[i++]);
    } else {
      result.push(b[j++]);
    }
  }

  while (i < a.length) {
    result.push(a[i++]);
  }

  while (j < b.length) {
    result.push(b[j++]);
  }

  return result;
}

function anagramGroups(words) {
  if (words.length === 0) return [];
  const map = new Map();
  for (const word of words) {
    const key = word.split('').sort().join('');
    if (!map.has(key)) {
      map.set(key, []);
    }
    map.get(key).push(word);
  }
