Two correctness issues remain:

- `pageSize <= 0` can produce incorrect results or an infinite loop. For example, a negative size makes `batch.length < pageSize` permanently false.
- Appending `?offset=...` is invalid when `endpoint` already contains a query string.

Validate the size and construct the URL safely:

```js
async function fetchAll(endpoint, pageSize) {
  if (!Number.isInteger(pageSize) || pageSize <= 0) {
    throw new RangeError("pageSize must be a positive integer");
  }

  const out = [];
  let offset = 0;

  while (true) {
    const url = new URL(endpoint, "http://placeholder");
    url.searchParams.set("offset", offset);
    url.searchParams.set("limit", pageSize);

    const batch = await get(url.href);
    out.push(...batch);

    if (batch.length < pageSize) break;
    offset += pageSize;
  }

  return out;
}
```

