Because `<` compares strings lexicographically when both operands are strings. It also handles `NaN` inconsistently.

Normalize and validate components before comparing:

```js
function compareVersions(a, b) {
  const len = Math.max(a.length, b.length);

  for (let i = 0; i < len; i++) {
    const x = Number(a[i] ?? 0);
    const y = Number(b[i] ?? 0);

    if (!Number.isFinite(x) || !Number.isFinite(y)) {
      throw new TypeError("Version components must be numeric");
    }
    if (x !== y) return x < y ? -1 : 1;
  }
  return 0;
}
```

